function hasOnlySmallFactors(n: number): boolean {
  if (n <= 0) return false;
  for (let d = 2; d * d <= n; d++) {
    while (n % d === 0) {
      if (d > 5) return false;
      n /= d;
    }
  }
  // whatever is left is 1 or a single prime
  return n <= 5;
}

