class Solution:
    def hasOnlySmallFactors(self, n: int) -> bool:
        if n <= 0:
            return False
        d = 2
        while d * d <= n:
            while n % d == 0:
                if d > 5:
                    return False
                n //= d
            d += 1
        # whatever is left is 1 or a single prime
        return n <= 5

